def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.

    Examples:
    For lst = [0,3,2,1,3,5,7,4,5,5,5,2,181,32,4,32,3,2,32,324,4,3] the output should be 10
    For lst = [1,0,1,8,2,4597,2,1,3,40,1,2,1,2,4,2,5,1] the output should be 25
    For lst = [1,3,1,32,5107,34,83278,109,163,23,2323,32,30,1,9,3] the output should be 13
    For lst = [0,724,32,71,99,32,6,0,5,91,83,0,5,6] the output should be 11
    For lst = [0,81,12,3,1,21] the output should be 3
    For lst = [0,8,1,2,1,7] the output should be 7
    """

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    def sum_digits(n):
        return sum(int(d) for d in str(abs(n)))

    primes = [x for x in lst if is_prime(x)]

    if not primes:
        return 0

    largest_prime = max(primes)
    return sum_digits(largest_prime)

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for num in range(2, n):
        if is_prime(num):
            primes.append(num)

    return primes

def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def sum_of_signed_digits(n):
        if n == 0:
            return 0
        if n < 0:
            # First digit is negative, rest are positive
            s = str(n)  # e.g., "-123"
            # The first character is '-', then digits
            # First signed digit is negative of the first digit
            first_digit = int(s[1])
            remaining_digits = [int(c) for c in s[2:]]
            return -first_digit + sum(remaining_digits)
        else:
            return sum(int(c) for c in str(n))

    count = 0
    for num in arr:
        if sum_of_signed_digits(num) > 0:
            count += 1
    return count

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test or test.strip() == '':
        return {}

    letters = test.split()

    if not letters:
        return {}

    # Count occurrences of each letter
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(counts.values())

    # Return all letters with the maximum count
    result = {letter: count for letter, count in counts.items() if count == max_count}

    return result

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Check if there are whitespaces
    if ' ' in txt or '\t' in txt or '\n' in txt or '\r' in txt:
        return txt.split()
    # Check if there are commas
    elif ',' in txt:
        return txt.split(',')
    else:
        # Count lower-case letters with odd order in the alphabet
        # ord('a') = 0, ord('b') = 1, ..., ord('z') = 25
        # So we need letters where (ord(c) - ord('a')) is odd
        count = 0
        for c in txt:
            if c.islower():
                order = ord(c) - ord('a')
                if order % 2 == 1:
                    count += 1
        return count

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def parse_value(v):
        """Convert a value (int, float, or string) to a float for comparison."""
        if isinstance(v, str):
            # Replace comma with dot for decimal parsing
            v = v.replace(',', '.')
            return float(v)
        else:
            return float(v)

    a_float = parse_value(a)
    b_float = parse_value(b)

    if a_float == b_float:
        return None
    elif a_float > b_float:
        return a
    else:
        return b

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    if is_prime(n):
        return x
    else:
        return y

def double_the_difference(lst):
    '''
    Given a list of numbers, return the sum of squares of the numbers
    in the list that are odd. Ignore numbers that are negative or not integers.

    double_the_difference([1, 3, 2, 0]) == 1 + 9 + 0 + 0 = 10
    double_the_difference([-1, -2, 0]) == 0
    double_the_difference([9, -2]) == 81
    double_the_difference([0]) == 0  

    If the input list is empty, return 0.
    '''
    total = 0
    for num in lst:
        # Check if the number is an integer (not a float with decimal part)
        # and is non-negative and is odd
        if isinstance(num, bool):
            continue
        if isinstance(num, int):
            if num >= 0 and num % 2 != 0:
                total += num * num
        elif isinstance(num, float):
            # Check if the float is actually an integer value
            if num == int(num) and num >= 0:
                int_num = int(num)
                if int_num % 2 != 0:
                    total += int_num * int_num
    return total

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    num_str = str(abs(num))
    even_count = 0
    odd_count = 0
    for digit in num_str:
        d = int(digit)
        if d % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

def solve(s):
    """You are given a string s.
    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    # Check if the string contains any letters
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        # Reverse the string if no letters are present
        return s[::-1]
    else:
        # Reverse the case of each letter, keep non-letters as is
        result = []
        for c in s:
            if c.isalpha():
                if c.islower():
                    result.append(c.upper())
                else:
                    result.append(c.lower())
            else:
                result.append(c)
        return ''.join(result)

import hashlib
def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
